// src/screens/OTPVerifyScreen.js
import React, { useState } from 'react';
import { View, Text, TextInput, Button, Alert, StyleSheet, Platform } from 'react-native';
import api from '../api';
import { saveToken, saveUser } from '../utilis/storage';

export default function OTPVerifyScreen({ route, navigation }) {
  const email = route.params?.email;
  const [otp, setOtp] = useState('');

  const verifyOTP = async () => {
    if (!otp) {
      Alert.alert('Error', 'Please enter OTP');
      return;
    }
    try {
      const res = await api.post('/auth/verify-otp', { email, otp: Number(otp) });

      await saveToken(res.data.token);
      await saveUser(res.data.user);
      Alert.alert('Success', 'OTP Verified');
      navigation.replace(
        res.data.user.role === 'faculty' ? 'FacultyHome' : 'StudentSelect'
      );
    } catch (err) {
      Alert.alert('Error', 'Invalid OTP');
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Enter OTP sent to {email}</Text>
      <TextInput
        placeholder="Enter OTP"
        value={otp}
        onChangeText={setOtp}
        keyboardType="numeric"
        style={styles.input}
      />
      <View style={styles.buttonWrapper}>
        <Button title="Verify OTP" onPress={verifyOTP} />
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { 
    flex: 1, 
    padding: 20, 
    backgroundColor: '#fff', 
    justifyContent: 'center',
    ...Platform.select({
      web: {
        pointerEvents: 'auto',
        boxShadow: '0px 1px 3px rgba(0,0,0,0.2)',
      },
    }),
  },
  title: { fontSize: 18, fontWeight: 'bold', marginBottom: 15 },
  input: {
    borderWidth: 1,
    borderColor: '#ccc',
    padding: 10,
    marginBottom: 15,
    borderRadius: 5,
    ...Platform.select({
      web: { pointerEvents: 'auto' },
    }),
  },
  buttonWrapper: {
    ...Platform.select({
      web: { pointerEvents: 'auto' },
    }),
  },
});
